"""Self-contained, inert-text browser UI for the T052 local reviewer."""

REVIEWER_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ABREX literature review</title>
<style>
:root{--ink:#17202a;--muted:#596776;--line:#d9e0e6;--paper:#fff;--bg:#f3f5f7;--nav:#173f4f;--blue:#176b87;--sf:#ffe08a;--lf:#bde9dc;--danger:#a12b2b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,sans-serif}header{background:var(--nav);color:#fff;padding:16px 24px}header h1{font-size:20px;margin:0 0 4px}.app{display:grid;grid-template-columns:250px minmax(0,1fr) 350px;gap:16px;max-width:1500px;margin:auto;padding:16px}.panel{background:var(--paper);border:1px solid var(--line);border-radius:10px;padding:16px;box-shadow:0 2px 9px #17202a0d}.sidebar{max-height:calc(100vh - 125px);overflow:auto;position:sticky;top:12px}.case{display:block;width:100%;border:0;border-left:4px solid transparent;background:#fff;color:var(--ink);padding:10px;text-align:left;cursor:pointer}.case:hover,.case:focus{background:#eef5f7}.case.active{background:#dceef3;border-left-color:var(--blue)}.case.reviewed::after{content:' ✓';color:#187044}.filters{display:flex;gap:6px;flex-wrap:wrap;margin:10px 0}.filters button.active{outline:3px solid #8bc4d4}button,.button{border:0;border-radius:6px;background:var(--blue);color:#fff;padding:9px 12px;font-weight:650;cursor:pointer;text-decoration:none}button.secondary,.button.secondary{background:#687783}button.ghost{background:#eaf0f3;color:#24333d}button:disabled{opacity:.55;cursor:wait}.toprow,.actions,.choice-row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.article-title{font-size:24px;margin:18px 0 4px}.source-line{color:var(--muted);margin-bottom:18px}.source-line a{color:var(--blue)}.instruction{font-size:18px;font-weight:650;margin:8px 0 14px}.passage-box{border:2px solid #91a8b3;border-radius:8px;background:#fff;padding:18px;margin:8px 0}.passage-box h3{margin:0 0 10px;font-size:14px;text-transform:uppercase;letter-spacing:.05em;color:#4a5963}.passage{white-space:pre-wrap;font:18px/1.85 Georgia,serif}.sf{background:var(--sf);border-bottom:3px solid #bc8500}.lf{background:var(--lf);border-bottom:3px solid #14725a}.both{background:linear-gradient(135deg,var(--sf) 50%,var(--lf) 50%)}.legend{display:flex;gap:14px;margin:8px 0;color:var(--muted)}.swatch{display:inline-block;width:18px;height:13px;margin-right:5px;vertical-align:-2px}.context{white-space:pre-wrap;background:#f4f6f7;padding:12px;border-radius:6px;margin-top:8px}.proposal{border:1px solid var(--line);border-radius:8px;padding:12px;margin:10px 0}.proposal.incomplete{border-left:5px solid #c47b14}.proposal h4{margin:0 0 6px}.choice-row label{border:1px solid var(--line);border-radius:6px;padding:6px 8px;cursor:pointer}.editor{border-top:1px solid var(--line);margin-top:12px;padding-top:12px}.field{display:block;margin:10px 0}.field input,.field textarea,.field select{display:block;width:100%;border:1px solid #aebbc3;border-radius:6px;padding:8px;font:inherit}.selection{padding:8px;background:#f4f6f7;border-radius:6px;min-height:38px}.banner,.readiness{padding:9px;border-radius:6px;margin:8px 0}.banner.ok,.readiness.ready{background:#e4f4e9;color:#155b2c}.banner.error,.readiness.not-ready{background:#fff0dc;color:#713f08}.missing{color:#8b4d00;font-weight:650}.working-file{overflow-wrap:anywhere}.missed{border:1px solid var(--line);border-radius:8px;padding:10px;margin:14px 0}.file-label{display:inline-block}.muted{color:var(--muted)}.hidden{display:none!important}details{margin:12px 0}summary{cursor:pointer;font-weight:650}.details-content{white-space:pre-wrap;font:13px/1.45 ui-monospace,monospace;background:#f5f6f7;padding:10px;overflow:auto}@media(max-width:1000px){.app{grid-template-columns:1fr}.sidebar{position:static;max-height:none}.case-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr))}}@media(max-width:520px){header{padding:12px}.app{padding:8px;gap:8px}.panel{padding:12px}.article-title{font-size:20px}.passage{font-size:17px}.actions button,.actions .button{width:100%}}
</style></head><body>
<header><h1 id="workflow-name">ABREX literature review</h1><div id="meta">Loading review packet…</div><div class="assisted-badge">Assisted review · suggestions are visible</div></header>
<div class="app">
<aside class="panel sidebar"><strong>Review cases</strong><div id="counts" class="muted"></div><div id="filters" class="filters"></div><div id="case-list" class="case-list"></div></aside>
<main class="panel"><div class="toprow"><button id="previous" class="ghost">Previous</button><button id="next" class="ghost">Next</button><span id="position" class="muted"></span></div><h2 id="article-title" class="article-title"></h2><div id="source-line" class="source-line"></div><p class="instruction">Review the proposed relations, then search the whole passage for anything missed.</p><div class="passage-box"><h3>Passage to review</h3><div class="legend"><span><i class="swatch sf"></i>Short form</span><span><i class="swatch lf"></i>Long form</span></div><div id="passage" class="passage" tabindex="0"></div></div><details><summary>Surrounding context</summary><div id="context" class="context"></div></details><h3>Proposed relations</h3><p class="muted">Suggestions are visible assisted-review history, not independent gold.</p><div id="proposals"></div><details><summary>Technical details</summary><label><input type="checkbox" id="reveal-methods"> Reveal method identities</label><div id="details" class="details-content"></div></details></main>
<aside class="panel"><h2>Your review</h2><div id="readiness" class="readiness not-ready">Checking what remains…</div><p class="muted working-file">Save target: <span id="working-file">loading…</span></p><div id="banner" class="banner hidden" role="status"></div><div class="missed"><strong>1. Search this whole passage for additional definitions.</strong><p class="muted">When finished, choose Searched. “Not yet” and “Uncertain” deliberately keep this passage incomplete.</p><div><label><input type="radio" name="missed" value="none"> Searched</label></div><div><label><input type="radio" name="missed" value="missed"> Not yet</label></div><div><label><input type="radio" name="missed" value="unsure"> Uncertain</label></div></div><p><strong>2. For every supported relation, use “Review relation details” and choose all three policy fields.</strong></p><div class="editor"><h3>Relation details / add relation</h3><p class="muted">To add or correct spans, select exact text in the passage. Repeated text is tracked by position.</p><div id="selection" class="selection">No text selected.</div><div class="choice-row"><button id="use-sf" class="ghost">Use as short form</button><button id="use-lf" class="ghost">Use as long form</button><button id="add-evidence" class="ghost">Add evidence fragment</button></div><div id="fragments" class="fragments"></div><label class="field">Short form<input id="sf-text" readonly></label><label class="field">Long form<input id="lf-text" readonly></label><label class="field">Interpretation — not a quotation<input id="interpretation" placeholder="Optional reconstructed interpretation"></label><div class="audit-fields"><label class="field">Relation kind<select id="relation-kind"><option value="uncertain">Choose…</option><option value="abbreviation_expansion">Abbreviation expansion</option><option value="other_naming_or_code_relation">Other naming or code relation</option></select></label><label class="field">Evidence structure<select id="evidence-structure"><option value="uncertain">Choose…</option><option value="contiguous_shared">Contiguous/shared</option><option value="discontinuous">Discontinuous</option></select></label><label class="field">Required context<select id="context-requirement"><option value="uncertain">Choose…</option><option value="text_alone">Text alone</option><option value="document_structure">Document structure</option><option value="image">Image</option></select></label><label><input id="source-error" type="checkbox"> Possible source error</label><label class="field">Relation note<textarea id="relation-notes" rows="2"></textarea></label></div><div class="choice-row"><button id="apply-correction">Save relation details</button><button id="add-pair">Add as new relation</button><button id="clear-editor" class="secondary">Clear</button></div></div><label class="field">Passage notes<textarea id="notes" rows="5"></textarea></label><div class="actions"><button id="save">Save passage</button><button id="save-next">Save and next incomplete</button><a class="button secondary" href="/api/export/json">JSON backup</a><a class="button secondary" href="/api/export/bioc">BioC XML</a></div><div class="actions" style="margin-top:8px"><label class="button secondary file-label">Import JSON<input id="import-json" class="hidden" type="file" accept="application/json"></label><label class="button secondary file-label">Import BioC<input id="import-bioc" class="hidden" type="file" accept=".xml,application/xml,text/xml"></label></div></aside>
</div>
<script>
'use strict';
const byId=id=>document.getElementById(id);let packet,state,readiness,index=0,filter='incomplete',draft,selectedSpan=null,editingDecision=null,dirty=false,saving=false;
const cpSlice=(text,start,end)=>Array.from(text).slice(start,end).join('');
function element(tag,text,className){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node}
function empty(node){while(node.firstChild)node.removeChild(node.firstChild)}
function showBanner(message,kind='ok'){const node=byId('banner');node.textContent=message;node.className='banner '+kind}
function caseAnnotation(c){return state.annotations[c.case_id]||null}
function baseSnapshot(c){return {pairs:c.suggestions.map(s=>({decision_id:'decision-'+s.suggestion_id,suggestion_id:s.suggestion_id,proposal_kind:s.proposal_kind,status:'unreviewed',short_form:s.short_form,long_form:s.long_form,origin:'assisted',notes:'',relation_kind:'uncertain',evidence_structure:'uncertain',context_requirement:'uncertain',evidence_spans:[],interpretation:'',source_error:false})),missed_definition:'unreviewed',notes:''}}
function mergedSnapshot(c){const saved=caseAnnotation(c),base=baseSnapshot(c);if(!saved)return base;const savedPairs=saved.current.pairs,bySuggestion=new Map(savedPairs.filter(p=>p.suggestion_id).map(p=>[p.suggestion_id,p]));return {...base,...saved.current,pairs:[...base.pairs.map(p=>bySuggestion.get(p.suggestion_id)||p),...savedPairs.filter(p=>!p.suggestion_id)]}}
function loadDraft(c){draft=structuredClone(mergedSnapshot(c));dirty=false;selectedSpan=null;editingDecision=null}
function pairIssues(p){const issues=[];if(p.status==='unreviewed'||p.status==='unsure')return ['support'];if(p.status==='incorrect')return issues;if(!p.short_form||!p.long_form)issues.push('exact spans');if(!p.relation_kind||p.relation_kind==='uncertain')issues.push('relation kind');if(!p.evidence_structure||p.evidence_structure==='uncertain')issues.push('evidence structure');else if(p.evidence_structure==='discontinuous'&&!(p.evidence_spans||[]).length)issues.push('evidence fragment');if(!p.context_requirement||p.context_requirement==='uncertain')issues.push('required context');return issues}
function snapshotIssues(c,snapshot=mergedSnapshot(c)){const issues=[];if(snapshot.missed_definition!=='none')issues.push('whole-passage search');snapshot.pairs.forEach(p=>issues.push(...pairIssues(p).map(x=>(p.short_form?.text||'relation')+': '+x)));return issues}
function caseMatches(c){const d=mergedSnapshot(c);if(filter==='all')return true;if(filter==='incomplete')return snapshotIssues(c,d).length>0;if(filter==='uncertain')return d.missed_definition==='unsure'||d.pairs.some(p=>p.status==='unsure');if(filter==='changed')return d.pairs.some(p=>p.origin!=='assisted');return c.category===filter}
function visibleCases(){return packet.cases.map((c,n)=>({c,n})).filter(x=>caseMatches(x.c))}
function reviewed(c){return snapshotIssues(c).length===0}
function renderCounts(){const done=packet.cases.filter(reviewed).length;byId('counts').textContent=done+' complete · '+(packet.cases.length-done)+' need attention'}
function renderFilters(){const host=byId('filters');empty(host);['incomplete','all','uncertain','changed',...new Set(packet.cases.map(c=>c.category))].forEach(value=>{const b=element('button',value==='all'?'All':value==='incomplete'?'Needs attention':value.replaceAll('_',' '),'ghost'+(filter===value?' active':''));b.addEventListener('click',async()=>{if(!(await saveIfDirty()))return;filter=value;renderFilters();renderList();const visible=visibleCases();if(visible.length&&!visible.some(x=>x.n===index))show(visible[0].n)});host.appendChild(b)})}
function renderList(){const host=byId('case-list');empty(host);visibleCases().forEach(({c,n})=>{const b=element('button',(n+1)+'. '+c.title,'case'+(n===index?' active':'')+(reviewed(c)?' reviewed':''));b.addEventListener('click',async()=>{if(n===index||await saveIfDirty())show(n)});host.appendChild(b)})}
function roleSegments(c){const spans=[];c.suggestions.forEach(s=>{if(s.short_form)spans.push({...s.short_form,role:'sf'});if(s.long_form)spans.push({...s.long_form,role:'lf'})});draft.pairs.forEach(p=>{if(p.short_form)spans.push({...p.short_form,role:'sf'});if(p.long_form)spans.push({...p.long_form,role:'lf'})});const bounds=[0,Array.from(c.text).length,...spans.flatMap(s=>[s.start,s.end])].sort((a,b)=>a-b);return [...new Set(bounds)].slice(0,-1).map((start,j)=>{const end=[...new Set(bounds)][j+1];const roles=new Set(spans.filter(s=>s.start<end&&s.end>start).map(s=>s.role));return {start,end,roles}})}
function renderPassage(c){const host=byId('passage');empty(host);roleSegments(c).forEach(seg=>{const text=cpSlice(c.text,seg.start,seg.end);if(!seg.roles.size){host.appendChild(document.createTextNode(text));return}const mark=element('mark',text,seg.roles.size===2?'both':[...seg.roles][0]);mark.setAttribute('aria-label',(seg.roles.has('sf')?'Short form':'')+(seg.roles.size===2?' and ':'')+(seg.roles.has('lf')?'Long form':''));host.appendChild(mark)})}
function choice(name,label,value,current,onchange){const wrapper=element('label');const radio=document.createElement('input');radio.type='radio';radio.name=name;radio.value=value;radio.checked=current===value;radio.setAttribute('aria-label',label);radio.addEventListener('change',onchange);wrapper.append(radio,document.createTextNode(' '+label));return wrapper}
function renderProposals(c){const host=byId('proposals');empty(host);draft.pairs.forEach((p,n)=>{const issues=pairIssues(p),box=element('div',undefined,'proposal'+(issues.length?' incomplete':''));const sf=p.short_form?p.short_form.text:'—';const lf=p.long_form?p.long_form.text:'—';box.appendChild(element('h4',p.proposal_kind==='span'?'Independent span proposal':lf+' → '+sf));box.appendChild(element('p','Status: '+(p.status==='correct'?'Supported':p.status==='incorrect'?'Unsupported':p.status==='unsure'?'Not sure':'Not reviewed')+' · Kind: '+(p.relation_kind||'uncertain').replaceAll('_',' ')+' · Evidence: '+(p.evidence_structure||'uncertain').replaceAll('_',' ')+' · Context: '+(p.context_requirement||'uncertain').replaceAll('_',' '),'muted'));if(issues.length)box.appendChild(element('p','Still needed: '+issues.join(', ')+'.','missing'));const row=element('div',undefined,'choice-row');[['correct','Supported'],['incorrect','Unsupported'],['unsure','Not sure']].forEach(([value,label])=>row.appendChild(choice('pair-'+n,label,value,p.status,()=>{p.status=value;dirty=true;renderAll()})));box.appendChild(row);const edit=element('button','Review relation details','ghost');edit.addEventListener('click',()=>startCorrection(p));box.appendChild(edit);if(!p.suggestion_id){const remove=element('button','Remove added relation','ghost');remove.addEventListener('click',()=>{draft.pairs.splice(n,1);dirty=true;renderAll()});box.appendChild(remove)}host.appendChild(box)});if(!draft.pairs.length)host.appendChild(element('p','No relation was proposed. Search the passage, then mark it Searched if none are missing.','muted'))}
function renderDetails(c){const revealed=byId('reveal-methods').checked;const methods=revealed?c.suggestions.map(s=>({suggestion_id:s.suggestion_id,method_ids:s.method_ids,provenance:s.provenance})):c.suggestions.map(s=>({suggestion_id:s.suggestion_id,method_ids:'hidden',provenance:'hidden'}));const diagnostics=revealed?c.method_diagnostics:c.method_diagnostics.map(d=>({status:d.status,coverage:d.coverage,diagnostics:d.diagnostics}));byId('details').textContent=JSON.stringify({case_id:c.case_id,inventory_id:c.inventory_id,section_id:c.section_id,passage_offsets:[c.passage_start,c.passage_end],suggestions:methods,method_diagnostics:diagnostics,structures:c.structures,source_comparisons:c.source_comparisons},null,2)}
function sourceLabel(c){return c.arm==='pmc_cc_by'?'Full-text article · '+c.section_heading:'PubMed abstract · '+c.section_heading}
function renderAll(){const c=packet.cases[index];byId('article-title').textContent=c.title;const source=byId('source-line');empty(source);source.append(document.createTextNode(sourceLabel(c)+' · '));const a=element('a','Open source');a.href=c.source_url;a.target='_blank';a.rel='noreferrer';source.appendChild(a);byId('context').textContent=[c.context_before,c.context_after].filter(Boolean).join('\n\n[Passage to review]\n\n');byId('position').textContent=(index+1)+' of '+packet.cases.length;renderPassage(c);renderProposals(c);renderDetails(c);byId('notes').value=draft.notes;document.querySelectorAll('input[name=missed]').forEach(r=>r.checked=r.value===draft.missed_definition);renderEditor();renderCounts();renderList()}
function show(n){index=n;loadDraft(packet.cases[index]);showBanner('Loaded case. Changes are saved to disk only when you use Save.');renderAll();history.replaceState(null,'','#case='+encodeURIComponent(packet.cases[index].case_id))}
function selectionOffsets(){const selection=window.getSelection(),host=byId('passage');if(!selection||selection.rangeCount!==1||selection.isCollapsed)return null;const range=selection.getRangeAt(0);if(!host.contains(range.commonAncestorContainer))return null;const prefix=range.cloneRange();prefix.selectNodeContents(host);prefix.setEnd(range.startContainer,range.startOffset);const start=Array.from(prefix.toString()).length,text=range.toString(),end=start+Array.from(text).length;if(!text||cpSlice(packet.cases[index].text,start,end)!==text)return null;return {start,end,text}}
function captureSelection(){selectedSpan=selectionOffsets();byId('selection').textContent=selectedSpan?'Selected: “'+selectedSpan.text+'”':'No text selected.'}
function startCorrection(pair){editingDecision=pair.decision_id;draft.editor=structuredClone(pair);renderEditor();byId('relation-kind').focus()}
function renderEditor(){const e=draft.editor||{};byId('sf-text').value=e.short_form?e.short_form.text:'';byId('lf-text').value=e.long_form?e.long_form.text:'';byId('interpretation').value=e.interpretation||'';byId('relation-kind').value=e.relation_kind||'uncertain';byId('evidence-structure').value=e.evidence_structure||'uncertain';byId('context-requirement').value=e.context_requirement||'uncertain';byId('source-error').checked=Boolean(e.source_error);byId('relation-notes').value=e.notes||'';const host=byId('fragments');empty(host);(e.evidence_spans||[]).forEach((span,i)=>{const row=element('div','Evidence '+(i+1)+': “'+span.text+'” ','fragment');const remove=element('button','Remove','ghost');remove.addEventListener('click',()=>{e.evidence_spans.splice(i,1);dirty=true;renderEditor()});row.appendChild(remove);host.appendChild(row)})}
function assign(role){selectedSpan=selectedSpan||selectionOffsets();if(!selectedSpan){showBanner('Select exact text in the passage first.','error');return}draft.editor=draft.editor||{};draft.editor[role]=selectedSpan;renderEditor()}
function spansOverlap(a,b){return Boolean(a&&b&&a.start<b.end&&b.start<a.end)}
function editorHasOverlaps(e){const spans=[e.short_form,e.long_form,...(e.evidence_spans||[])].filter(Boolean);return spans.some((left,i)=>spans.slice(i+1).some(right=>spansOverlap(left,right)))}
function addEvidence(){selectedSpan=selectedSpan||selectionOffsets();if(!selectedSpan){showBanner('Select exact text in the passage first.','error');return}draft.editor=draft.editor||{};draft.editor.evidence_spans=draft.editor.evidence_spans||[];const occupied=[draft.editor.short_form,draft.editor.long_form,...draft.editor.evidence_spans];if(occupied.some(span=>spansOverlap(span,selectedSpan))){showBanner('Evidence fragments cannot overlap the short form, long form, or another evidence fragment.','error');return}draft.editor.evidence_spans.push(selectedSpan);draft.editor.evidence_spans.sort((a,b)=>a.start-b.start);selectedSpan=null;byId('selection').textContent='No text selected.';renderEditor()}
function clearEditor(){delete draft.editor;editingDecision=null;selectedSpan=null;byId('selection').textContent='No text selected.';renderEditor()}
function editorFields(e){return {relation_kind:byId('relation-kind').value,evidence_structure:byId('evidence-structure').value,context_requirement:byId('context-requirement').value,interpretation:byId('interpretation').value,source_error:byId('source-error').checked,evidence_spans:e.evidence_spans||[],notes:byId('relation-notes').value}}
function applyCorrection(){if(!editingDecision){showBanner('Choose Review relation details on a relation first.','error');return}const pair=draft.pairs.find(p=>p.decision_id===editingDecision);if(!pair)return;const e=draft.editor||{};if(!e.short_form&&!e.long_form){showBanner('A relation needs at least one source span.','error');return}if(byId('evidence-structure').value==='discontinuous'&&editorHasOverlaps(e)){showBanner('A discontinuous relation cannot contain overlapping source spans.','error');return}const changedSpans=JSON.stringify(pair.short_form)!==JSON.stringify(e.short_form)||JSON.stringify(pair.long_form)!==JSON.stringify(e.long_form);Object.assign(pair,{short_form:e.short_form||null,long_form:e.long_form||null},editorFields(e));if(changedSpans&&pair.suggestion_id)pair.origin='corrected';dirty=true;clearEditor();renderAll();showBanner('Relation details staged. Save passage to write them to disk.')}
function addPair(){const e=draft.editor||{};if(!e.short_form||!e.long_form){showBanner('An added relation needs both a short form and long form.','error');return}if(byId('evidence-structure').value==='discontinuous'&&editorHasOverlaps(e)){showBanner('A discontinuous relation cannot contain overlapping source spans.','error');return}draft.pairs.push(Object.assign({decision_id:'added-'+crypto.randomUUID(),suggestion_id:null,proposal_kind:'definition',status:'unsure',short_form:e.short_form,long_form:e.long_form,origin:'added'},editorFields(e)));draft.missed_definition='missed';dirty=true;clearEditor();renderAll();showBanner('Relation staged. Complete its support and details, then save the passage.')}
async function responseJson(response){let body;try{body=await response.json()}catch{throw Error('The reviewer returned an unreadable response.')}if(!response.ok)throw Error(body.error||'Request failed ('+response.status+').');return body}
async function refreshReadiness(){readiness=await responseJson(await fetch('/api/readiness'));const node=byId('readiness');node.className='readiness '+(readiness.complete?'ready':'not-ready');node.textContent=readiness.complete?'Ready: all '+readiness.required_cases+' required passages are complete.':'Not ready: '+readiness.remaining_cases+' passages and '+readiness.remaining_items+' decisions still need attention.'}
async function save(goNext=false){if(saving)return false;saving=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{draft.notes=byId('notes').value;delete draft.editor;const c=packet.cases[index],existing=caseAnnotation(c);const body={schema_version:'t052-annotation-submission-v2',packet_id:packet.packet_id,packet_content_sha256:packet.content_sha256,current_case_id:c.case_id,annotations:{[c.case_id]:{expected_revision:existing?existing.revision:0,decision:draft}}};state=await responseJson(await fetch('/api/annotations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}));dirty=false;await refreshReadiness();showBanner('Saved revision '+state.annotations[c.case_id].revision+' to '+packet._workflow.working_file+'.');renderCounts();renderList();if(goNext){filter='incomplete';renderFilters();const next=visibleCases().find(x=>x.n!==index);if(next)show(next.n)}return true}catch(error){showBanner('Save failed: '+error.message+'. You are still on this case; your edits remain on screen.','error');return false}finally{saving=false;document.querySelectorAll('button').forEach(b=>b.disabled=false)}}
async function saveIfDirty(){return dirty?save(false):true}
async function navigate(delta){if(!(await saveIfDirty()))return;const visible=visibleCases(),at=visible.findIndex(x=>x.n===index),next=visible[(at+delta+visible.length)%visible.length];if(next!==undefined)show(next.n)}
async function importFile(file,kind){if(!file)return;try{const body=await file.arrayBuffer(),type=kind==='json'?'application/json':'application/xml';state=await responseJson(await fetch('/api/import/'+kind,{method:'POST',headers:{'Content-Type':type},body}));const resume=state.current_case_id,found=packet.cases.findIndex(c=>c.case_id===resume);show(found>=0?found:index);showBanner((kind==='json'?'JSON':'BioC')+' import validated and saved.')}catch(error){showBanner('Import failed: '+error.message,'error')}}
async function init(){try{packet=await responseJson(await fetch('/api/packet'));state=await responseJson(await fetch('/api/annotations'));await refreshReadiness();byId('workflow-name').textContent=packet._workflow.name;byId('working-file').textContent=packet._workflow.working_file;byId('meta').textContent=packet.cases.length+' required passages · '+packet.packet_id+' · content '+packet.content_sha256.slice(0,12);renderFilters();const hash=new URLSearchParams(location.hash.slice(1)).get('case'),wanted=hash||state.current_case_id,found=packet.cases.findIndex(c=>c.case_id===wanted),visible=visibleCases();show(found>=0&&caseMatches(packet.cases[found])?found:visible.length?visible[0].n:0)}catch(error){showBanner('Reviewer could not load: '+error.message,'error');byId('meta').textContent='Load failed'}}
byId('passage').addEventListener('mouseup',captureSelection);byId('passage').addEventListener('keyup',captureSelection);document.addEventListener('selectionchange',()=>{if(document.getSelection()?.rangeCount)captureSelection()});byId('use-sf').addEventListener('click',()=>assign('short_form'));byId('use-lf').addEventListener('click',()=>assign('long_form'));byId('add-evidence').addEventListener('click',addEvidence);byId('apply-correction').addEventListener('click',applyCorrection);byId('add-pair').addEventListener('click',addPair);byId('clear-editor').addEventListener('click',clearEditor);byId('notes').addEventListener('input',()=>dirty=true);['interpretation','relation-kind','evidence-structure','context-requirement','source-error','relation-notes'].forEach(id=>byId(id).addEventListener('change',()=>dirty=true));document.querySelectorAll('input[name=missed]').forEach(r=>r.addEventListener('change',()=>{draft.missed_definition=r.value;dirty=true;renderCounts()}));byId('reveal-methods').addEventListener('change',()=>renderDetails(packet.cases[index]));byId('save').addEventListener('click',()=>save(false));byId('save-next').addEventListener('click',()=>save(true));byId('previous').addEventListener('click',()=>navigate(-1));byId('next').addEventListener('click',()=>navigate(1));byId('import-json').addEventListener('change',event=>importFile(event.target.files[0],'json'));byId('import-bioc').addEventListener('change',event=>importFile(event.target.files[0],'bioc'));window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue=''}});init();
</script></body></html>"""
